import type { FastifyInstance } from 'fastify';
import { OutcomeAssessmentSchema } from '@publipulse/shared';
import type { ActorResolver } from './signal-store.js';
import type { OutcomeStore } from './outcome-store.js';
import { canCreateOutcomeAssessment, canReadOutcomeAssessments } from './outcome-store.js';
import { parseQueryLimit } from './request-validation.js';
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
export async function registerOutcomeRoutes(app:FastifyInstance,opts:{resolveActor:ActorResolver;store:OutcomeStore}):Promise<void>{
 app.post('/v1/signals/:signalId/outcomes',async(req,reply)=>{const actor=await opts.resolveActor(req.headers.authorization,typeof req.headers['x-organization-id']==='string'?req.headers['x-organization-id']:undefined);if(!actor)return reply.code(401).send({error:'authentication_required',requestId:req.id});if(!canCreateOutcomeAssessment(actor))return reply.code(403).send({error:'insufficient_permissions',requestId:req.id});const {signalId}=req.params as {signalId?:string};if(!signalId||!UUID.test(signalId))return reply.code(400).send({error:'invalid_signal_id',requestId:req.id});const clientMutationId=typeof req.headers['x-client-mutation-id']==='string'?req.headers['x-client-mutation-id']:undefined;if(clientMutationId&&!UUID.test(clientMutationId))return reply.code(400).send({error:'invalid_client_mutation_id',requestId:req.id});const parsed=OutcomeAssessmentSchema.safeParse(req.body);if(!parsed.success)return reply.code(400).send({error:'invalid_outcome_assessment',issues:parsed.error.issues.map(i=>({path:i.path.join('.'),code:i.code})),requestId:req.id});const r=await opts.store.create(actor,signalId,parsed.data,clientMutationId);if(r.kind==='signal_not_found')return reply.code(404).send({error:'signal_not_found',requestId:req.id});if(r.kind==='action_not_found')return reply.code(404).send({error:'action_not_found_for_signal',requestId:req.id});if(r.kind==='mutation_conflict')return reply.code(409).send({error:'client_mutation_id_conflict',requestId:req.id});return reply.code(201).send({outcome:r.outcome});});
 app.get('/v1/signals/:signalId/outcomes',async(req,reply)=>{const actor=await opts.resolveActor(req.headers.authorization,typeof req.headers['x-organization-id']==='string'?req.headers['x-organization-id']:undefined);if(!actor)return reply.code(401).send({error:'authentication_required',requestId:req.id});if(!canReadOutcomeAssessments(actor))return reply.code(403).send({error:'insufficient_permissions',requestId:req.id});const {signalId}=req.params as {signalId?:string};if(!signalId||!UUID.test(signalId))return reply.code(400).send({error:'invalid_signal_id',requestId:req.id});const query=req.query as {limit?:unknown};const limit=parseQueryLimit(query.limit);if(limit===null)return reply.code(400).send({error:'invalid_limit',requestId:req.id});const rows=await opts.store.list(actor,signalId,limit);if(rows===null)return reply.code(404).send({error:'signal_not_found',requestId:req.id});return reply.send({outcomes:rows});});
}
